124	  children,
125	  onClose,
126	  title,
127	  titleId,
128	  titleStyle = 'large',
129	  labelledBy,
130	  ariaLabel,
131	  boxedHeader,
132	  contentStyles,
133	  headerStyles,
134	  headerTitleStyles,
135	  closeButtonStyles,
