import React, { useState } from 'react';
import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { chakra } from '@chakra-ui/react';
import { expect, userEvent, waitForElementToBeRemoved, within } from 'storybook/test';
import { ZimmDrawer } from './index';
import type { ZimmDrawerSize } from './index';

const meta: Meta<typeof ZimmDrawer> = {
  title: 'Elements/ZimmDrawer',
  component: ZimmDrawer,
};
export default meta;
type Story = StoryObj<typeof ZimmDrawer>;

/**
 * Generic chrome only — no tab/header content here (see Commerce/ZimmPdpDrawer for a real
 * consumer). Proves the shell renders with the expected dialog semantics at each size variant.
 */
// Named component rather than an inline `render: () => { useState(...) }` — see zimmModal's
// story for why a lowercase `render` can't call hooks directly.
const OpenDrawerExample = ({ size }: { size: ZimmDrawerSize }) => {
  const [isOpen, setIsOpen] = useState(true);
  return (
    <ZimmDrawer isOpen={isOpen} onClose={() => setIsOpen(false)} size={size} aria-label="Example drawer">
      <chakra.p padding="var(--zimm-scale-xl)">Generic ZimmDrawer chrome with arbitrary children.</chakra.p>
    </ZimmDrawer>
  );
};

export const Large: Story = {
  render: () => <OpenDrawerExample size="large" />,
  play: async () => {
    // Portal renders outside canvasElement — testing.md §Layer-2 exception. Chakra's Drawer is
    // built on its Modal primitive, which renders DrawerContent via a Portal by default, so
    // within(canvasElement) can't reach it.
    const doc = within(document.body);
    const dialog = await doc.findByRole('dialog');
    await expect(dialog).toBeInTheDocument();
    await expect(dialog).toHaveAttribute('aria-label', 'Example drawer');
  },
};

export const Tablet: Story = {
  render: () => <OpenDrawerExample size="tablet" />,
};

export const Small: Story = {
  render: () => <OpenDrawerExample size="small" />,
};

export const XLarge: Story = {
  render: () => <OpenDrawerExample size="xLarge" />,
};

export const Mobile: Story = {
  render: () => <OpenDrawerExample size="mobile" />,
};

export const Prompt: Story = {
  render: () => <OpenDrawerExample size="prompt" />,
};

export const CloseButtonClosesTheDrawer: Story = {
  render: () => <OpenDrawerExample size="large" />,
  play: async () => {
    // Portal renders outside canvasElement — testing.md §Layer-2 exception (see Large's play).
    const doc = within(document.body);
    const dialog = await doc.findByRole('dialog');
    await expect(dialog).toBeInTheDocument();

    await userEvent.click(doc.getByRole('button', { name: /close/i }));

    // Chakra's Drawer plays a slide-out exit transition (framer-motion) before AnimatePresence
    // actually unmounts the dialog node — an immediate `queryByRole('dialog')` assertion here
    // catches it mid-animation, still present with a near-100% translateX. Wait for the real
    // removal instead of asserting the instant after the click.
    await waitForElementToBeRemoved(dialog);
  },
};

// --- Title header variants ---

const WithTitleExample = ({ size, titleStyle }: { size: ZimmDrawerSize; titleStyle?: 'large' | 'small' }) => {
  const [isOpen, setIsOpen] = useState(true);
  return (
    <ZimmDrawer isOpen={isOpen} onClose={() => setIsOpen(false)} size={size} title="SIGN IN" titleStyle={titleStyle}>
      <chakra.p padding="var(--zimm-scale-xl)">Drawer body content.</chakra.p>
    </ZimmDrawer>
  );
};

/** Inline header row: title on the left, close button on the right — Figma Heading (Large) style. */
export const WithTitleLarge: Story = {
  render: () => <WithTitleExample size="large" titleStyle="large" />,
  play: async () => {
    // Portal renders outside canvasElement — testing.md §Layer-2 exception (see Large's play).
    const doc = within(document.body);
    // Queried by computed accessible name rather than a specific aria-* attribute: ZimmDrawer's
    // custom ZimmDrawerContent sets aria-labelledby to the visible title span's id for the title
    // case (see index.tsx's own comment on why aria-label isn't needed here) — this asserts the
    // real outcome without pinning the test to which mechanism produces it.
    const dialog = await doc.findByRole('dialog', { name: 'SIGN IN' });
    await expect(dialog).toBeInTheDocument();
    await expect(doc.getByText('SIGN IN')).toBeInTheDocument();
  },
};

/** Inline header with body2Strong (14px bold) title — Figma Heading (Small) / textStyle="body2Strong". */
export const WithTitleSmallStyle: Story = {
  render: () => <WithTitleExample size="large" titleStyle="small" />,
};

/** Small-width drawer with inline title header. */
export const WithTitleSmallDrawer: Story = {
  render: () => <WithTitleExample size="small" titleStyle="large" />,
};

/** Title close button dismisses the drawer. */
export const TitleCloseButtonClosesTheDrawer: Story = {
  render: () => <WithTitleExample size="large" />,
  play: async () => {
    // Portal renders outside canvasElement — testing.md §Layer-2 exception (see Large's play).
    const doc = within(document.body);
    const dialog = await doc.findByRole('dialog');
    await expect(dialog).toBeInTheDocument();

    await userEvent.click(doc.getByRole('button', { name: /close/i }));

    await waitForElementToBeRemoved(dialog);
  },
};

import { breakpoints } from 'app/theme/foundation';

// SFCC-831 — layout only, for both the `location` and `language` variants of
// ZimmCountryLanguageMismatch (index.tsx). Figma confirms both variants share one layout at
// every breakpoint (SFCC-831 decisions.md #3 "Component structure": "Identical across both
// variants: Header + Body + Button-group"; #4 "Tablet content layout: None. Tablet content
// symbol is byte-identical to Desktop Small") — nothing here varies by variant; VARIATION_CONFIG
// in index.tsx handles the only thing that does (copy/callbacks).
//
// No `_hover`/`_active`/`_focusVisible`/`_disabled` rule exists in this file, deliberately —
// Figma's own properties for this component are Size/Variant/Step, and both banners are
// `Step=–` (SFCC-831 decisions.md #5: "Interaction states: None exist... States come from
// ZimmDrawer/ZimmButton recipes"). Every interactive element (both CTAs) renders as a real
// ZimmButton and inherits its own hover/press/focus/disabled treatment from zimmButton.css.ts —
// a second styling surface here would only drift from that over time (see
// .claude/rules/overrideStyling.md's "One canonical styling surface per component type").

export const ZimmCountryLanguageMismatch = {
  parts: ['root', 'content', 'buttonGroup'],
  baseStyle: {
    // Content→button-group gap (SFCC-831 decisions.md #3: "80px content→buttons desktop/tablet
    // (space/2000), 64px mobile (space/1600)") — --zimm-scale-5xl (spacing.ts: 5rem = 80px) and
    // --zimm-scale-4xl (spacing.ts: 4rem = 64px) are exact matches, no new token needed.
    //
    // Edge padding: ZimmDrawer's own `content` part (zimmDrawer.css.ts) carries none — every
    // drawer body supplies its own — and no Figma value for this component's own edge padding
    // was captured in SFCC-831's decision record (only the two gaps in this file were). Matches
    // the nearest real precedent for the same situation instead of inventing a number:
    // zimmAuthDrawerContent.css.ts's own `root.padding` (var(--zimm-scale-xl)) — a content
    // block's edge padding inside this same ZimmDrawer shell, used at size="small", the same
    // width class as size="prompt". Not independently confirmed against this component's own
    // Figma frame — flagged in the SFCC-831 Step B1 build report, not silently assumed.
    root: {
      display: 'flex',
      flexDirection: 'column',
      width: '100%',
      padding: 'var(--zimm-scale-xl)',
      gap: 'var(--zimm-scale-4xl)',
      [`@media (min-width: ${breakpoints.md})`]: {
        gap: 'var(--zimm-scale-5xl)',
      },
    },
    // Heading + body copy stack. Same "no captured Figma value" situation as root's padding
    // above — matches zimmAuthDrawerContent.css.ts's own `signupStack` gap
    // (var(--zimm-scale-m)), the same heading-plus-body-copy grouping concept in the same drawer
    // shell.
    content: {
      display: 'flex',
      flexDirection: 'column',
      width: '100%',
      gap: 'var(--zimm-scale-m)',
    },
    // A vertical CTA stack, not a horizontal row. SFCC-831 decisions.md #6's own arithmetic
    // ("Button-group is 120px desktop/tablet (2×52+16) and 96px mobile (2×40+16)") only resolves
    // against ZimmButton's own size="adaptive" HEIGHT (52px desktop / 40px mobile —
    // zimmButton/index.tsx's own doc comment), stacked with a 16px gap between them
    // (space/400) — --zimm-scale-m (1rem = 16px) is an exact match. A horizontal reading would
    // require each button to be exactly 52px/40px *wide*, which contradicts decisions.md #8's
    // own `min-w-80` (80px min-width) figure for the same buttons.
    buttonGroup: {
      display: 'flex',
      flexDirection: 'column',
      width: '100%',
      gap: 'var(--zimm-scale-m)',
    },
  },
};

