      'borderBottomWidth', 'borderBottomStyle', 'borderBottomColor',
      'boxShadow',
      'outlineWidth', 'outlineStyle', 'outlineColor',
    ];

    return {
      dialogCount: dialogs.length,
      dialogTag: dialog ? dialog.tagName : null,
      dialogAriaLabel: dialog ? dialog.getAttribute('aria-label') : null,
      dialogAriaLabelledby: dialog ? dialog.getAttribute('aria-labelledby') : null,
      dialogChildCount: dialog ? dialog.children.length : null,
      headerTag: header ? header.tagName : null,
      headerChildTags: header ? Array.from(header.children).map((c) => c.tagName) : null,
      secondChildTag: secondChild ? secondChild.tagName : null,
      // Structural-separation checks (DOM inspection, not eyeballing)
      headerContainsCloseBtn: header && closeBtn ? header.contains(closeBtn) : null,
      headerContainsHeading: header && heading ? header.contains(heading) : header && withHeading ? false : null,
      secondChildContainsHeading: secondChild && heading ? secondChild.contains(heading) : null,
      secondChildContainsCloseBtn: secondChild && closeBtn ? secondChild.contains(closeBtn) : null,
      headerIsPriorSiblingOfSecondChild: header && secondChild ? header.nextElementSibling === secondChild : null,
      // Rects
      dialogRect: rectOf(dialog),
      headerRect: rectOf(header),
      secondChildRect: rectOf(secondChild),
      headingRect: rectOf(heading),
      closeSvgRectViaDom: rectOf(closeSvg),
      // Computed styles
      dialogBg: csOf(dialog, ['backgroundColor']),
      headerFullStyle: csOf(header, fullHeaderProps),
      secondChildBg: csOf(secondChild, ['backgroundColor']),
      viewportWidth: window.innerWidth,
      viewportHeight: window.innerHeight,
    };
  }, withHeading);
}

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const results = {};

  for (const target of TARGETS) {
    for (const vp of target.viewports) {
      const resultKey = `${target.key}__${vp.label}(${vp.w}x${vp.h})`;
      await page.setViewportSize({ width: vp.w, height: vp.h });
      await page.goto(`${STORYBOOK}${target.id}&viewMode=story`, { waitUntil: 'load' });
      await page.waitForSelector('[role="dialog"]', { timeout: 15000 });
      await waitForStableRect(page);
      // extra settle buffer past the 300ms framer-motion enter transition
      await page.waitForTimeout(200);

      const domData = await gatherDomData(page, target.withHeading);

      // Close button svg via Playwright locator (accessible-name based, robust to markup)
      let closeSvgBox = null;
      try {
        const closeButtonLocator = page.getByRole('button', { name: /close/i });
        const svgLocator = closeButtonLocator.locator('svg').first();
        closeSvgBox = await svgLocator.boundingBox();
      } catch (e) {
        closeSvgBox = { error: String(e) };
      }

      const screenshotPath = `/tmp/sfcc831_${target.key}_${vp.label}.png`;
      await page.screenshot({ path: screenshotPath });

      let distanceFromRightEdge = null;
      if (domData.dialogRect && closeSvgBox && !closeSvgBox.error) {
        distanceFromRightEdge = Math.round((domData.dialogRect.right - (closeSvgBox.x + closeSvgBox.width)) * 100) / 100;
      }

      let headerContentBgMatch = null;
      if (domData.headerFullStyle && domData.dialogBg) {
        headerContentBgMatch = domData.headerFullStyle.backgroundColor === domData.dialogBg.backgroundColor;
      }

      let headerHeadingOverlap = null;
      if (domData.headerRect && domData.headingRect) {
        headerHeadingOverlap = domData.headerRect.bottom > domData.headingRect.top;
      }

      results[resultKey] = {
        storyId: target.id,
        viewport: vp,
        screenshotPath,
        domData,
        closeSvgBoxViaLocator: closeSvgBox,
        derived: {
          headerVsDialogContentBgMatch: headerContentBgMatch,
          headerBottom_lte_headingTop: headerHeadingOverlap === null ? null : !headerHeadingOverlap,
          closeSvgDistanceFromDialogRightEdge: distanceFromRightEdge,
        },
      };
    }
  }

  await browser.close();
  console.log(JSON.stringify(results, null, 2));
})();
